package com.aurum.scalp;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class RepositoryPolicyTest {
 @Test public void brokerFourHourEndOverridesUtcGrid(){long t=java.time.Instant.parse("2026-11-12T23:00:00Z").toEpochMilli();Market.Candle c=new Market.Candle(t,4000,4001,3999,4000,t+14400000);assertTrue(Market.closed(Collections.singletonList(c),14400000,t+3600000).isEmpty());assertEquals(1,Market.closed(Collections.singletonList(c),14400000,t+14400000).size());}
 @Test public void providerLimitBlocksAllFramesAndManualRefreshAcrossSessions(){PollPolicy p=new PollPolicy();assertTrue(p.claim("quote",1000,false));p.complete("quote",1000,60000,true);for(String k:new String[]{"quote","M1","H1","H4"}){assertFalse(p.claim(k,2000,false));assertFalse(p.claim(k,2000,true));}assertTrue(p.claim("H1",61000,false));}
 @Test public void successfulEndpointCannotEraseShared429(){PollPolicy p=new PollPolicy();p.claim("H1",1000,false);p.claim("quote",1000,false);p.complete("quote",1000,60000,true);p.complete("H1",2000,100,false);assertFalse(p.claim("H4",5000,true));}
 @Test public void resumeDoesNotFetchBeforeOriginalDueTime(){PollPolicy p=new PollPolicy();assertTrue(p.claim("H1",100,false));p.complete("H1",100,180000,false);assertFalse(p.claim("H1",200,false));assertTrue(p.claim("H1",180100,false));}
 @Test public void reservationPreventsDuplicateAcrossSessions(){PollPolicy p=new PollPolicy();assertTrue(p.claim("quote",0,false));assertFalse(p.claim("quote",100,true));p.release("quote");assertTrue(p.claim("quote",100,true));}
 @Test public void unreasonableRetryHasOneHourUpperBound(){assertEquals(3600000,RetryGate.retryAfter("999999999",0));PollPolicy p=new PollPolicy();p.claim("quote",0,false);p.complete("quote",0,Long.MAX_VALUE,true);assertEquals(3600000,p.remaining(0));}
 @Test public void trustedClockAdvancesMonotonicallyWithoutPhoneWallTime(){MarketClock c=new MarketClock();assertEquals(0,c.now(100));c.sync(1760000000000L,100);assertEquals(1760000180000L,c.now(180100));assertEquals(0,c.now(99));}
 @Test public void staleTickNeverSetsClock(){MarketClock c=new MarketClock();c.sync(1760000000000L,100);Market.Quote q=new Market.Quote(1759999880000L,4000,4001);assertEquals("● STALE",Market.quoteState(q,true,c.now(100)));}
 @Test public void futureQuoteIsNotLive(){assertEquals("● TIME UNVERIFIED",Market.quoteState(new Market.Quote(1800000000000L,4000,4001),true,1799999820000L));}
 @Test public void newerClosedCandleReplacesSavedQuoteReference(){long t=1760000000000L;Market.Candle c=new Market.Candle(t,4100,4101,4099,4100);ZoneEngine.Analysis a=new ZoneEngine.Analysis(Market.Frame.M1,Collections.singletonList(c),Collections.emptyList(),Collections.emptyList(),1,0,"range");assertEquals(4100,Market.referencePrice(new Market.Quote(t-86400000,4000,4001),Collections.singletonList(a)),0);assertEquals(4200.5,Market.referencePrice(new Market.Quote(t+61000,4200,4201),Collections.singletonList(a)),0);}
 @Test public void priorDayIgnoresMalformedNewestDate(){long now=java.time.Instant.parse("2026-11-13T12:00:00Z").toEpochMilli(),valid=java.time.Instant.parse("2026-11-11T12:00:00Z").toEpochMilli();Map<Market.Frame,List<Market.Candle>> data=new EnumMap<>(Market.Frame.class);data.put(Market.Frame.M5,Arrays.asList(new Market.Candle(valid,4000,4001,3999,4000),new Market.Candle(valid+86400000+1000,4000,4001,3999,4000)));assertEquals(valid/86400000,Market.priorSession(data,now).day);}
}
